WITH exploded AS (SELECT id, service, host, level, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, value), valid AS (SELECT id, host, level, latency_ms, status_code, attr_key, CASE WHEN level IN ('INFO', 'WARN') THEN 'Core' ELSE 'Other' END AS level_group, CONCAT_WS(',', attr_key, level) AS attr_key_level_key FROM exploded WHERE attr_key IS NOT NULL), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY host ORDER BY status_code, id, attr_key) AS rank_in_group FROM valid QUALIFY rank_in_group = 1), ranked_app_logs AS (SELECT id, status_code, attr_key, level_group, attr_key_level_key, rank_in_group FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY attr_key, host ORDER BY status_code, id, attr_key) AS row_num FROM ranked) ranked WHERE row_num = 1), metrics AS (SELECT id, attr_key, attr_key_level_key, rank_in_group, COUNT(status_code) OVER w_recent AS last7_count_status_code, MIN(status_code) OVER w_recent AS last7_min_status_code, MAX(status_code) OVER w_recent AS last7_max_status_code, AVG(status_code) OVER w_recent AS last7_avg_status_code FROM ranked_app_logs WHERE rank_in_group > 1 WINDOW w_recent AS (PARTITION BY attr_key ORDER BY status_code, id, attr_key ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY last7_avg_status_code NULLS LAST, id, attr_key) AS rn FROM metrics QUALIFY rn = 1) SELECT CASE WHEN last7_count_status_code >= 14 THEN 'PREMIUM' ELSE 'STANDARD' END AS last7_count_status_code_tier, attr_key, ROUND(AVG(last7_avg_status_code), 2) AS avg_last7_avg_status_code, AVG(last7_min_status_code) FILTER (WHERE attr_key = 'region') AS region_avg_last7_min_status_code, PERCENTILE_APPROX(last7_min_status_code, 0.9) AS last7_min_status_code_p90, MAX(last7_max_status_code) AS max_last7_max_status_code FROM deduped GROUP BY CASE WHEN last7_count_status_code >= 14 THEN 'PREMIUM' ELSE 'STANDARD' END, attr_key;
